head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        rdo_gubun.setValue("1");
        await scwin.init();
        // fn_list_sync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05936.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    const dateTmp = $c.ut.cGetToday("yyyymmdd");
    cmb_month1.setValue(dateTmp.substring(4, 6));
    cmb_month2.setValue(dateTmp.substring(4, 6));
    cmb_month3.setValue(dateTmp.substring(4, 6));

    // 기준년 (콤보박스)
    const sbmOptions = {
        id : "sbm_dts_year1",
        action : "/ElwNcr.do",
        ref : "",
        target : "dts_year1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_year2",
        action : "/ElwNcr.do",
        ref : "",
        target : "dts_year2=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_year3",
        action : "/ElwNcr.do",
        ref : "",
        target : "dts_year3=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /*dts_inst.DataID = "/etn/EtnCodeAct.do?method=listIsurCd&For=R";
    dts_inst.Reset();*/

    const sbmOptions4 = {
        id : "sbm_dts_inst",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_inst=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions5 = {
        id : "sbm_dts_lp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_lp=body.content",
        isProcessMsg : false
    };

    const sbmRtn5 = await $c.sbm.executeDynamic(sbmOptions5);
    // TODO Stage2: sbmRtn5 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    /*dts_lp.DataID = "/etn/EtnCodeAct.do?method=listLPCd&For=R";
    dts_lp.Reset();*/

    /*dts_LpMbrNo.DataID = "/CodeAction.do?method=listLeadCom&For=R";
    dts_LpMbrNo.Reset(); */

    cmb_inst_lp.ComboDataID = "dts_inst";
    scwin.changeGubun("1");
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
     * @method
     * @name rdo_gubun_onselchange
     * @description rdo_gubun onselchange 이벤트
     * @returns {void}
     * @hidden N
     */
scwin.rdo_gubun_onselchange = function() {
    try {
        scwin.changeGubun(rdo_gubun.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05936.rdo_gubun_onselchange" });
    }
};

/**
 * @method
 * @name cmb_instlp_select2_onselchange
 * @description cmb_instlp_select2 onselchange 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_instlp_select2_onselchange = async function() {
    try {
        if (cmb_instlp_select2.BindColVal === "01") {
            cmb_inst_lp.ComboDataID = "dts_inst";
        } else if (cmb_instlp_select2.BindColVal === "02") {
            cmb_inst_lp.ComboDataID = "dts_lp";
        } else {
            await $c.win.alert(cmb_instlp_select2.BindColVal);
        }
        cmb_inst_lp.setSelectedIndex(0);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05936.cmb_instlp_select2_onselchange" });
    }
};

/**
 * @method
 * @name dts_year1_OnLoadError
 * @description dts_year1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_year1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Year1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05936.dts_year1_OnLoadError" });
    }
};

