/**
 * @method
 * @name dts_list_OnLoadError
 * @description dts_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_list_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_list);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05936.dts_list_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_list_OnLoadCompleted
 * @description dts_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_list_OnLoadCompleted = function(rowcount) {
    //    FillGridHeaderTotalCnt(rowcount, panel_page);
    // alert("dts_List.CountRow-->"+dts_List.CountRow);

};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05936.btn_search_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function() {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05936.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF05936.xml", SCREN_PROCS_TP_CD_07);
        scwin.excelDown();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05936.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 데이타 가져와서 뿌리기 List
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&inputMessageId=ELW_LP_NCR_INOUT&outputMessageId=ELW_LP_NCR_INOUT";
    if (rdo_gubun.getValue() === "1") {
        if (cmb_instlp_select1.BindColVal === "01") url += "&GUBUN=isur";

        else url += "&GUBUN=lp";
        url += "&FROM_YYMM=" + cmb_year1.BindColVal + cmb_month1.BindColVal;
        $c.cm.setColumnProp(grid_list, 'NCR_PRE1', 'Show', true);
        $c.cm.setColumnProp(grid_list, 'NCR_PRE2', 'Show', true);
    } else {
        if (cmb_instlp_select2.BindColVal === "01") url += "&GUBUN=isur";

        else url += "&GUBUN=lp";
        url += "&FROM_YYMM=" + cmb_year2.BindColVal + cmb_month2.BindColVal;
        url += "&TO_YYMM=" + cmb_year3.BindColVal + cmb_month3.BindColVal;
        url += "&ISUR_LP_CD=" + cmb_inst_lp.BindColVal;
        $c.cm.setColumnProp(grid_list, 'NCR_PRE1', 'Show', false);
        $c.cm.setColumnProp(grid_list, 'NCR_PRE2', 'Show', false);
    }
    const sbmOptions = {
        id : "sbm_dts_list",
        action : "/ElwNcr.do",
        ref : "",
        target : "dts_list=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name changeGubun
 * @description change Gubun 처리
 * @param {*} gubun gubun
 * @returns {void}
 * @hidden N
 */
scwin.changeGubun = function(gubun) {
    if (gubun === "1") {
        cmb_instlp_select1.setDisabled(true);
        cmb_year1.setDisabled(true);
        cmb_month1.setDisabled(true);
        cmb_instlp_select2.setDisabled(true);
        cmb_inst_lp.setDisabled(true);
        cmb_year2.setDisabled(true);
        cmb_month2.setDisabled(true);
        cmb_year3.setDisabled(true);
        cmb_month3.setDisabled(true);
    } else if (gubun === "2") {
        cmb_instlp_select1.setDisabled(true);
        cmb_year1.setDisabled(true);
        cmb_month1.setDisabled(true);
        cmb_instlp_select2.setDisabled(true);
        cmb_inst_lp.setDisabled(true);
        cmb_year2.setDisabled(true);
        cmb_month2.setDisabled(true);
        cmb_year3.setDisabled(true);
        cmb_month3.setDisabled(true);
    }
};

/**
 * @method
 * @name excelDown
 * @description 엑셀 다운로드
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    $c.data.downloadGridViewExcel(grid_list, {fileName: "ELW LP (영업용)순자본비율", type: "8"});
};
